import pytest

import shipping
from shipping import shipping_cost


def test_module_imports():
    assert hasattr(shipping, "shipping_cost")


@pytest.mark.parametrize(
    "zone, expected",
    [("domestic", 5.00), ("eu", 12.00), ("intl", 25.00)],
)
def test_base_price_by_zone(zone, expected):
    assert shipping_cost(1.0, zone) == expected


@pytest.mark.parametrize("zone", ["", "DOMESTIC", "us", "mars"])
def test_unknown_zone_raises(zone):
    with pytest.raises(ValueError):
        shipping_cost(1.0, zone)


@pytest.mark.parametrize("weight", [0, 0.0, -1, -0.1])
def test_non_positive_weight_raises(weight):
    with pytest.raises(ValueError):
        shipping_cost(weight, "eu")


@pytest.mark.parametrize(
    "weight, expected",
    [
        (1.0, 12.00),  # first kg is included in base price
        (1.2, 14.00),  # one started extra kg
        (2.0, 14.00),
        (3.0, 16.00),  # two extra kg
        (3.1, 18.00),  # three started extra kg
    ],
)
def test_started_kilograms_above_first_add_two(weight, expected):
    assert shipping_cost(weight, "eu") == expected


def test_express_doubles_total():
    assert shipping_cost(3.1, "intl", express=True) == pytest.approx(62.00)


def test_express_domestic_light_parcel_is_not_free():
    assert shipping_cost(0.5, "domestic", express=True) == 10.00


@pytest.mark.parametrize("weight", [0.1, 0.5])
def test_domestic_light_non_express_is_free(weight):
    assert shipping_cost(weight, "domestic") == 0.00


def test_domestic_just_over_half_kg_is_charged():
    assert shipping_cost(0.6, "domestic") == 5.00


def test_free_rule_only_applies_to_domestic():
    assert shipping_cost(0.5, "eu") == 12.00
    assert shipping_cost(0.5, "intl") == 25.00


def test_result_rounded_to_two_decimals():
    assert shipping_cost(1.0, "domestic", express=True) == 10.00
    assert round(shipping_cost(2.7, "intl"), 2) == shipping_cost(2.7, "intl")

